import {canCountGear} from './repo-policy.js';
export const METRICS={matk:['MATK',''],mpPct:['Max MP','%'],attackSpeed:['สปีดตี','%'],hpRegen:['ฟื้น HP/s',''],castSpeed:['ร่ายไว','%'],healPower:['พลังฮีล',''],block:['Block','%'],reference:['เอฟเฟกต์อ้างอิง',''],atk:['ATK',''],atkPct:['ATK','%'],matkPct:['MATK','%'],hp:['Max HP',''],hpPct:['Max HP','%'],mp:['Max MP',''],str:['STR',''],agi:['AGI',''],vit:['VIT',''],int:['INT',''],dex:['DEX',''],luk:['LUK',''],crit:['โอกาสคริ','%'],critDamage:['ดาเมจคริ','%'],cdr:['ลด CD สกิล','%'],def:['DEF',''],softDef:['Soft DEF',''],hit:['HIT',''],flee:['FLEE',''],lifesteal:['ดูดเลือด','%'],armorPierce:['เจาะเกราะ','%'],ccDamage:['ดาเมจใส่เป้าติด CC','%'],speed:['สปีดวิ่ง','%'],bossDamage:['ดาเมจ Elite / Mini-boss','%'],debuffDamage:['ดาเมจใส่เป้าติดดีบัฟ','%'],trigger:['Trigger / เอฟเฟกต์พิเศษ','']};
export const clone=x=>structuredClone(x);
export const REGION_RULES={Valebrook:{name:'Hearthland',one:'Max HP +6% · Gold +6%',two:'Max HP +6% · เรทดรอป +6%'},Ashford:{name:'Emberheart',one:'ATK / MATK +5%',two:'ดาเมจคริ +6% · ATK / MATK +3%'},Stormwall:{name:'Frostbound',one:'ลดดาเมจ 5%',two:'ลดดาเมจ 4% · Max HP +8%'},Sanctum:{name:'Riftsight',one:'ลด CD 4% · คริ +2%',two:'ลด CD 3% · คริ +2% · เรทวิญญาณ +15%'},Tidehaven:{name:'Tidebound',one:'ลดดาเมจ 3% · ATK / MATK +3%',two:'Max HP +6% · เรทดรอป +4% · ลด CD 2%'}};
export const KIN_RULES={Skitter:['Swarm Instinct','คริ +2%'],Hound:['Pack Bond','สปีดตี +5%'],Thornling:['Bramble Pact','ดาเมจใส่มอนติดดีบัฟ +8%'],Brute:['Hide of Giants','Max HP +6%'],Crab:['Shellguard','สะท้อนดาเมจจากมอน 12%'],Pebblit:['Pebble Wall','ลดดาเมจ 3%'],Sprout:['Deep Roots','VIT +3 · STR +3'],Lurker:['Mire Ambush','ดาเมจใส่มอน HP >90% +10%'],Wisp:["Will-o’-Chorus",'MATK +5%'],Remnant:['Echoing Oath','ลด CD 4%']};
export const COLOUR_RULES={Attack:['Crimson Mastery','ATK / MATK +3%'],Guard:['Azure Mastery','ลดดาเมจ 3% · HP +3%'],Growth:['Verdant Mastery','Gold +5% · ดรอป +3% · Gathering −3%'],Spirit:['Violet Mastery','ลด CD 3% · คริ +1%'],Legendary:['Sovereign Mastery','ดาเมจ Field Boss +8% · HP +4%']};
export function resonance(profile,catalog){const seen=new Set(),regions={},kins={},colours={};let load=0;for(const slug of profile.cards){const c=catalog.find(x=>x.s===slug);if(!c)continue;load+=c.l;if(seen.has(slug))continue;seen.add(slug);const region=c.r==='Nacreon'?'Tidehaven':c.r;regions[region]=(regions[region]||0)+1;kins[c.t]=(kins[c.t]||0)+1;if((profile.cardStars?.[slug]||5)>=3)colours[c.c]=(colours[c.c]||0)+1;}const active=[];for(const [r,n]of Object.entries(regions)){const rule=REGION_RULES[r];if(rule&&n>=3)active.push({id:'region:'+r,name:rule.name+(n>=5?' II':' I'),count:n,threshold:n>=5?5:3,effect:rule.one+(n>=5?' · '+rule.two:''),kind:'Region'});}for(const [k,n]of Object.entries(kins)){const rule=KIN_RULES[k];if(rule&&n>=2)active.push({id:'kin:'+k,name:rule[0],count:n,threshold:2,effect:rule[1],kind:'Kin'});}for(const [c,n]of Object.entries(colours)){const rule=COLOUR_RULES[c],limit=c==='Legendary'?2:3;if(rule&&n>=limit)active.push({id:'colour:'+c,name:rule[0],count:n,threshold:limit,effect:rule[1],kind:'Colour'});}return {active,load,regions,kins,colours,slots:profile.cards.length};}
export function aggregateGear(profile){const totals={};for(const gear of profile.gear){if(!canCountGear(gear))continue;const coeff=Number(gear.coefficient??1);for(const s of [...gear.stats,...(gear.affixLayoutValid!==false?gear.affixes:[])]){if(['trigger','reference'].includes(s.key)||s.sourceStatus==='conflict'||!Object.hasOwn(METRICS,s.key))continue;totals[s.key]=(totals[s.key]||0)+Number(s.value)*coeff;}}return totals;}
export function gearDelta(profile,base){const a=aggregateGear(profile),b=aggregateGear(base);return Object.keys(METRICS).filter(k=>k!=='trigger').map(key=>({key,before:b[key]||0,after:a[key]||0,delta:Math.round(((a[key]||0)-(b[key]||0))*100)/100}));}
export function skillWarnings(profile,base){const warnings=[];const total=profile.skills.reduce((s,x)=>s+x.level,0),budget=base.skills.reduce((s,x)=>s+x.level,0);if(total>budget)warnings.push(`ใช้แต้ม ${total}/${budget} เกินชุดตั้งต้น ${total-budget} แต้ม`);for(const branch of ['Assassin','Trickery','Shadow']){const list=profile.skills.filter(x=>x.branch===branch);for(let i=1;i<list.length;i++)if(list[i].level>0&&list[i-1].level<3)warnings.push(`${list[i].name} ต้องมี ${list[i-1].name} Lv3`);}for(const skill of profile.skills){const need=['Fade','Adrenaline'].includes(skill.name)?3:5;if(skill.evo&&skill.level<need)warnings.push(`${skill.name} Evolution ต้อง Lv${need}`);}return warnings;}
export function validateProfile(input,base,catalog){if(!input||typeof input!=='object')throw Error('รูปแบบบิลด์ไม่ถูกต้อง');const p=clone(base);p.name=String(input.name||'บิลด์นำเข้า').slice(0,80);const allowed=new Set(catalog.map(c=>c.s));if(!Array.isArray(input.cards)||input.cards.length>9||input.cards.some(x=>!allowed.has(x)))throw Error('รายการการ์ดไม่ถูกต้อง');p.cards=[...input.cards];p.cardStars={};for(const slug of p.cards){const n=input.cardStars?.[slug]??5;if(n!==1&&n!==5)throw Error('รองรับการ์ด ★1 และ ★5 เท่านั้น');p.cardStars[slug]=n;}for(const key of Object.keys(base.attrs)){const n=Number(input.attrs?.[key]);if(!Number.isFinite(n)||n<0||n>99)throw Error('สเตตัสพื้นฐานต้องอยู่ระหว่าง 0–99');p.attrs[key]=n;}if(!Array.isArray(input.gear)||input.gear.length!==base.gear.length)throw Error('จำนวนช่องอุปกรณ์ไม่ถูกต้อง');p.gear=base.gear.map(original=>{const g=input.gear.find(x=>x.id===original.id);if(!g)throw Error('ไม่พบช่องอุปกรณ์ '+original.id);const result=clone(original);result.itemSlug=String(g.itemSlug||original.itemSlug||'').slice(0,100);result.rarity=['Normal','Magic','Rare','Epic'].includes(g.rarity)?g.rarity:original.rarity;result.name=String(g.name||original.name).slice(0,150);result.enchant=Number(g.enchant);if(!Number.isInteger(result.enchant)||result.enchant<0||result.enchant>15)throw Error('ค่าตีบวกไม่ถูกต้อง');result.enabled=g.enabled!==false;result.roleConfirmed=g.roleConfirmed===true;result.set=String(g.set||'').slice(0,50);result.notes=String(g.notes||'').slice(0,5000);result.coefficient=Number(g.coefficient??1);if(!Number.isFinite(result.coefficient)||result.coefficient<0||result.coefficient>1)throw Error('ตัวคูณอุปกรณ์ต้องอยู่ระหว่าง 0–1');for(const type of ['stats','affixes']){if(!Array.isArray(g[type])||g[type].length>20)throw Error('รายการออฟไม่ถูกต้อง');result[type]=g[type].map(s=>{if(!Object.hasOwn(METRICS,s.key)||!Number.isFinite(Number(s.value))||Math.abs(Number(s.value))>10000000)throw Error('ค่าออฟไม่ถูกต้อง');return {key:s.key,value:Number(s.value),kind:['trigger','reference'].includes(s.key)?s.key:METRICS[s.key][1]==='%'?'percent':'flat',...(type==='affixes'?{name:String(s.name||'ออฟทดลอง').slice(0,100),tier:/^T[1-8]$/.test(s.tier)?s.tier:'T8'}:{})};});}return result;});if(!Array.isArray(input.skills)||input.skills.length!==base.skills.length)throw Error('สกิลไม่ครบ');p.skills=base.skills.map(s=>{const item=input.skills.find(x=>x.name===s.name);const n=Number(item?.level);if(!Number.isInteger(n)||n<0||n>s.max)throw Error('เลเวลสกิลไม่ถูกต้อง');return {...s,level:n,evo:['A','B'].includes(item.evo)?item.evo:''};});p.target=String(input.target||base.target);p.night=!!input.night;return p;}
